#include <spacerad/PartitionStudy.h>
#include <QCoreApplication>
#include <QDir>
#include <QEventLoop>
#include <QFile>
#include <QFileInfo>
#include <QPointer>
#include <QTimer>
#include <functional>
#include <iostream>
#include <stdexcept>
using namespace spacerad;
namespace {
Json checks=Json::array();
void check(bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);std::cout<<"PASS "<<name<<std::endl;}
QByteArray read(const QString& p){QFile f(p);if(!f.open(QIODevice::ReadOnly))throw std::runtime_error("Cannot read acceptance file");return f.readAll();}
void write(const QString& p,const QByteArray& b){QFile f(p);if(!f.open(QIODevice::WriteOnly|QIODevice::Truncate)||f.write(b)!=b.size())throw std::runtime_error("Cannot write acceptance file");}
bool rejects(const std::function<void()>& f){try{f();return false;}catch(...){return true;}}
void wait(PartitionStudyService& service,int timeoutMs=120000){QEventLoop loop;QString error;QTimer timer;timer.setSingleShot(true);auto done=QObject::connect(&service,&PartitionStudyService::completed,&loop,&QEventLoop::quit);auto fail=QObject::connect(&service,&PartitionStudyService::failed,&loop,[&](const QString& s){error=s;loop.quit();});auto state=QObject::connect(&service,&PartitionStudyService::stateChanged,&loop,[&](const QString& s){if(s=="cancelled")loop.quit();});QObject::connect(&timer,&QTimer::timeout,&loop,[&]{error="Native study timed out";service.cancel();loop.quit();});timer.start(timeoutMs);loop.exec();QObject::disconnect(done);QObject::disconnect(fail);QObject::disconnect(state);if(!error.isEmpty())throw std::runtime_error(error.toStdString());}
Project fixture(){auto p=Project::demo();p.radius=30;p.volumes={{"Shell","G4_Al",{0,0,0},{30,30,30},.5,false},{"Si","G4_Si",{0,0,0},{20,20,20},0,true}};p.spectra.clear();for(const auto& name:{"e-","proton"}){engine::Spectrum s;s.particle=name;s.energy={1,5};s.values={1,1};s.prepare();p.spectra.push_back(s);}p.validate();return p;}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(argc!=3)return 2;QString out=QFileInfo(QString::fromLocal8Bit(argv[2])).absoluteFilePath();if(QFileInfo::exists(out)||!QDir().mkpath(out))return 2;bool passed=false;
try{auto runtime=loadRuntimeFile(QString::fromLocal8Bit(argv[1]));auto p=fixture();auto before=p.toJson();auto config=defaultPartitionStudySettings(p,50);ShieldingScanSettings scan{"Shell",{.5,1}};PartitionStudyService service;service.configure(runtime);int complete=0,progress=0;QObject::connect(&service,&PartitionStudyService::completed,&service,[&](const QByteArray&){++complete;});QObject::connect(&service,&PartitionStudyService::progress,&service,[&](int,int,qint64 n,qint64 total){if(n>=0&&n<=total)++progress;});service.start(p,scan,config,out+"/job");check(service.running(),"Real native study starts");check(rejects([&]{service.start(p,scan,config,out+"/busy");})&&!QFileInfo::exists(out+"/busy"),"Busy rejection creates no second output");check(rejects([&]{service.configure(runtime);}),"Runtime reconfiguration rejected while running");wait(service);check(service.state()=="completed"&&complete==1&&!service.result().isEmpty(),"Complete native study accepts one result");auto report=Json::parse(service.result().toStdString());check(report.at("scans").size()==24&&report.at("rows").size()==2&&report.at("total_histories")==3200,"Actual two-species native study budget and coverage");check(progress>0,"Native study emits bounded transport progress");check(loadPartitionStudy(out+"/job")==report,"Offline native reconstruction equals accepted result");check(p.toJson()==before,"Native study preserves input project");
    auto tamper=[&](const char* file,const char* name){QString path=out+"/job/"+file;auto saved=read(path);write(path,saved+" ");bool rejected=rejects([&]{loadPartitionStudy(out+"/job");});write(path,saved);check(rejected,name);};
    tamper("study-plan.json","Plan hash tamper rejected");tamper("study-result.json","Aggregate result hash tamper rejected");tamper("study.csv","Aggregate CSV tamper rejected");tamper("scan-000000/scan.csv","Child scan CSV tamper rejected");tamper("scan-000000/cases/case-000000/result.json","Raw transport result tamper rejected");check(loadPartitionStudy(out+"/job")==report,"Restored archive revalidates");
    service.start(p,scan,config,out+"/cancel");QTimer::singleShot(20,&service,&PartitionStudyService::cancel);wait(service);check(service.state()=="cancelled"&&service.result().isEmpty()&&complete==1,"Cancellation never publishes full result");auto cancelled=loadPartitionStudy(out+"/cancel");check(cancelled.at("status")=="cancelled"&&cancelled.at("rows").empty(),"Cancelled archive preserves terminal partial state");
    bool restarted=false;auto* leaf=service.findChild<ShieldingScanService*>();auto restart=QObject::connect(leaf,&ShieldingScanService::completed,&service,[&](const QByteArray&){if(restarted)return;restarted=true;service.cancel();service.start(p,scan,config,out+"/restarted");QTimer::singleShot(1,&service,&PartitionStudyService::cancel);});service.start(p,scan,config,out+"/restart-origin");wait(service);if(service.running())wait(service);QObject::disconnect(restart);check(restarted&&service.state()=="cancelled"&&loadPartitionStudy(out+"/restarted").at("completed_scans")==0,"Cancel/restart discards queued callbacks from previous study");
    auto* destroyed=new PartitionStudyService;destroyed->configure(runtime);auto longConfig=defaultPartitionStudySettings(p,1000000);destroyed->start(p,scan,longConfig,out+"/destroyed");QPointer<PartitionStudyService> guard=destroyed;QEventLoop loop;QTimer::singleShot(20,&loop,[&]{delete destroyed;loop.quit();});loop.exec();check(guard.isNull()&&loadPartitionStudy(out+"/destroyed").at("status")=="cancelled","Destroying active study terminates children and records cancellation");
    auto* reentrant=new PartitionStudyService;reentrant->configure(runtime);QPointer<PartitionStudyService> alive=reentrant;QObject::connect(reentrant,&PartitionStudyService::stateChanged,&app,[&](const QString& s){if(s=="running"&&alive)delete alive.data();});reentrant->start(p,scan,config,out+"/reentrant");check(alive.isNull()&&loadPartitionStudy(out+"/reentrant").at("status")=="cancelled","Host can destroy study directly from running signal");passed=true;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';}write(out+"/summary.json",QByteArray::fromStdString(Json{{"passed",passed},{"checks",checks}}.dump(2)));std::cout<<checks.size()<<" real native partition checks; passed="<<passed<<'\n';return passed?0:1;}
